//! Vanilla identifiers from the `schema/vanilla` folder of the rockide/schemas release that
//! [`crate::docs::schemas`] downloads: the enums of `$defs` such as `item_identifier` or
//! `texture_path`, generated by that project from the public vanilla packs.

use std::{
    collections::{HashMap, HashSet},
    fs,
    path::Path,
};

use serde_json::Value;

use super::Kind;
use crate::error::{Error, Result, bail};

/// Where each kind's vanilla names live: a file under `schema/vanilla` and a `$defs` entry.
const SOURCES: &[(Kind, &str, &str)] = &[
    (Kind::Item, "server/identifiers.json", "item_identifier"),
    // Every block has an item form, so recipes and loot can name blocks as items.
    (Kind::Item, "server/identifiers.json", "block_identifier"),
    (Kind::Block, "server/identifiers.json", "block_identifier"),
    (Kind::Entity, "server/identifiers.json", "entity_identifier"),
    (Kind::LootTable, "server/paths.json", "loot_table_path"),
    (Kind::TradeTable, "server/paths.json", "trading_path"),
    (
        Kind::TerrainTexture,
        "client/identifiers.json",
        "terrain_texture_identifier",
    ),
    (
        Kind::ItemTexture,
        "client/identifiers.json",
        "item_texture_identifier",
    ),
    (Kind::Texture, "client/paths.json", "texture_path"),
    (
        Kind::Geometry,
        "client/identifiers.json",
        "geometry_identifier",
    ),
    (Kind::Geometry, "reference/block_geometry.json", "v2"),
    (
        Kind::RenderController,
        "client/identifiers.json",
        "render_controller_identifier",
    ),
    (
        Kind::Animation,
        "client/identifiers.json",
        "animation_identifier",
    ),
    (
        Kind::Animation,
        "client/identifiers.json",
        "animation_controller_identifier",
    ),
    (
        Kind::BehaviorAnimation,
        "client/identifiers.json",
        "animation_identifier",
    ),
    (
        Kind::BehaviorAnimation,
        "client/identifiers.json",
        "animation_controller_identifier",
    ),
    (Kind::Sound, "client/identifiers.json", "sound_identifier"),
    (Kind::SoundFile, "client/paths.json", "sound_path"),
    (
        Kind::Particle,
        "client/identifiers.json",
        "particle_identifier",
    ),
];

/// The vanilla names of each kind, normalized like the add-on's.
pub struct Vanilla {
    /// The rockide/schemas release the names come from, e.g. `0.1.4`.
    pub version: String,
    names: HashMap<Kind, HashSet<String>>,
}

impl Vanilla {
    /// Read the vanilla lists of the release extracted at `release`.
    pub fn load(release: &Path, version: String) -> Result<Self> {
        let root = release.join("schema").join("vanilla");
        let mut files: HashMap<&str, Value> = HashMap::new();
        let mut names: HashMap<Kind, HashSet<String>> = HashMap::new();
        for &(kind, file, def) in SOURCES {
            if !files.contains_key(file) {
                let path = root.join(file);
                let text = fs::read_to_string(&path)
                    .map_err(|error| Error::msg(format!("{}: {error}", path.display())))?;
                files.insert(file, serde_json::from_str(&text)?);
            }
            let Some(node) = files[file].pointer(&format!("/$defs/{def}")) else {
                bail!("{file} has no $defs/{def}.");
            };
            let set = names.entry(kind).or_default();
            enums(node, &mut |name| {
                set.insert(kind.normalize(name));
            });
        }
        Ok(Self { version, names })
    }

    #[cfg(test)]
    pub fn from_lists(lists: &[(Kind, &[&str])]) -> Self {
        let mut names: HashMap<Kind, HashSet<String>> = HashMap::new();
        for (kind, list) in lists {
            names
                .entry(*kind)
                .or_default()
                .extend(list.iter().map(|name| kind.normalize(name)));
        }
        Self {
            version: "test".into(),
            names,
        }
    }

    /// Whether vanilla has `name` (already normalized) of `kind`.
    pub fn contains(&self, kind: Kind, name: &str) -> bool {
        self.names.get(&kind).is_some_and(|set| set.contains(name))
    }
}

/// Every string of every `enum` under `node`, without following `$ref`s.
fn enums(node: &Value, found: &mut impl FnMut(&str)) {
    match node {
        Value::Object(map) => {
            if let Some(Value::Array(names)) = map.get("enum") {
                names.iter().filter_map(Value::as_str).for_each(&mut *found);
            }
            map.values().for_each(|value| enums(value, found));
        }
        Value::Array(items) => items.iter().for_each(|item| enums(item, found)),
        _ => {}
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::testdir::TestDir;

    #[test]
    fn reads_the_enums_of_each_list() {
        let dir = TestDir::new("vanilla");
        let root = dir.path().join("schema/vanilla");
        let identifiers = |defs: &[&str]| {
            let defs: serde_json::Map<_, _> = defs
                .iter()
                .map(|def| (def.to_string(), serde_json::json!({ "anyOf": [{ "type": "string" }, { "enum": [format!("minecraft:{def}")] }] })))
                .collect();
            serde_json::json!({ "$defs": defs }).to_string()
        };
        let files: HashSet<&str> = SOURCES.iter().map(|(_, file, _)| *file).collect();
        for file in files {
            let defs: Vec<&str> = SOURCES
                .iter()
                .filter(|(_, f, _)| *f == file)
                .map(|(_, _, def)| *def)
                .collect();
            let path = root.join(file);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, identifiers(&defs)).unwrap();
        }
        let vanilla = Vanilla::load(dir.path(), "test".into()).unwrap();
        assert!(vanilla.contains(Kind::Item, "minecraft:block_identifier"));
        assert!(vanilla.contains(Kind::Entity, "minecraft:entity_identifier"));
        assert!(!vanilla.contains(Kind::Block, "minecraft:item_identifier"));

        fs::write(root.join("server/paths.json"), "{\"$defs\": {}}").unwrap();
        let error = Vanilla::load(dir.path(), "test".into()).err().unwrap();
        assert!(error.to_string().contains("loot_table_path"));
    }
}
